构建失败（exit 101）多半是因为把 `Arc<Mutex<Shared>>` / `Arc<Condvar>` 传给了需要 `&Mutex<Shared>` / `&Condvar` 的函数；应使用 `as_ref()`。下面是按规格 R1–R10 修正后的完整程序：

```rust
use concir_sync::Semaphore;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Shared {
    ready: bool,
}

fn waiter(m: &Mutex<Shared>, cv: &Condvar) {
    let mut guard = m.lock().unwrap();
    while !guard.ready {
        guard = cv.wait(guard).unwrap();
    }
}

fn notifier(m: &Mutex<Shared>, cv: &Condvar) {
    let mut guard = m.lock().unwrap();
    guard.ready = true;
    cv.notify_one();
}

fn main() {
    let m = Arc::new(Mutex::new(Shared { ready: false }));
    let cv = Arc::new(Condvar::new());
    let sem = Semaphore::new(2);

    let release_w = sem.acquire();
    let release_n = sem.acquire();

    let m_w = Arc::clone(&m);
    let cv_w = Arc::clone(&cv);
    let waiter_handle = thread::spawn(move || {
        waiter(m_w.as_ref(), cv_w.as_ref());
        drop(release_w);
    });

    let m_n = Arc::clone(&m);
    let cv_n = Arc::clone(&cv);
    let notifier_handle = thread::spawn(move || {
        notifier(m_n.as_ref(), cv_n.as_ref());
        drop(release_n);
    });

    let _wait_w = sem.acquire();
    let _wait_n = sem.acquire();

    waiter_handle.join().unwrap();
    notifier_handle.join().unwrap();

    println!("DONE ready=true");
}
```
